import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const group = new Group();

  // Plane geometry sized to match atlas region aspect ratio (512×320 ≈ 1.6:1)
  const geometry = new PlaneGeometry(2, 1.25);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    side: ctx.THREE.DoubleSide, // allow faint back-lighting if needed
  });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load brushed-metal texture (synchronous function defers mapping)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // No cinematic primitives – node ships static
  // No event handlers – no interactions

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
  };

  group.userData.handlers = {};

  return group;
}
